import itertools, json

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

def valid(d1, d2):
    for r in riders:
        if d1[r] == d2[r]:
            return False
        if r == "R" and "F" in (d1[r], d2[r]):
            return False
        if r == "Y" and "J" in (d1[r], d2[r]):
            return False
    if "H" not in (d1["T"], d2["T"]):
        return False
    if d2["S"] != d1["Y"]:
        return False
    return True

options = {
    "A": lambda d1, d2: d2["R"] == "G",
    "B": lambda d1, d2: d1["S"] == "H",
    "C": lambda d1, d2: d2["Y"] == "H",
    "D": lambda d1, d2: "J" in (d1["S"], d2["S"]),
    "E": lambda d1, d2: "G" in (d1["T"], d2["T"]),
}

perms = [dict(zip(riders, p)) for p in itertools.permutations(bikes)]
sols = [(a, b) for a in perms for b in perms
        if a["T"] == "J" and valid(a, b)]

possible = [k for k, f in options.items() if any(f(a, b) for a, b in sols)]
final = possible[0] if len(possible) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {"num_scenarios": len(sols), "possible_options": possible}
}))
